-- =============================================================================
-- CATALOGUE DE RÉPARATION — PlayStation 5
--
-- PROVENANCE : contrairement à supabase/catalog-reparations.sql, ce fichier ne
-- vient PAS du document « Liste de réparation » du client — la PS5 n'y figure
-- pas. Les modèles et les pannes ci-dessous sont les pannes courantes de la
-- gamme PlayStation 5, calquées sur la structure retenue pour la PS4 dans le
-- document (mêmes catégories, mêmes formulations), et complétées par ce qui est
-- propre à la PS5 : HDMI 2.1, métal liquide, SSD M.2, lecteur amovible.
--
-- À FAIRE RELIRE PAR L'ATELIER avant mise en ligne : c'est le seul fichier du
-- dépôt dont le contenu ne provient pas du client.
--
-- Aucun tarif n'est importé : comme les 887 prestations du document, chaque
-- ligne arrive à 0 € et « tarif à configurer », donc « sur devis » côté client
-- tant qu'un prix n'a pas été saisi dans Catalogue → Réparations.
--
-- Rejouable : aucune suppression, aucun écrasement de prix.
--
--   psql "$DB_URL" -f supabase/catalog-ps5.sql
-- =============================================================================

set search_path = public, extensions;

-- ---------------------------------------------------------------------------
-- Les 5 modèles de la gamme PlayStation 5
-- ---------------------------------------------------------------------------
insert into public.console_models (brand_id, name, slug, short_name, release_year, display_order, family, is_retro, is_handheld, variants, common_issues, is_active)
select b.id, 'PlayStation 5', 'ps5', 'PS5', 2020, 7, 'ps5', false, false,
       array['Standard (CFI-1000 à 1200)', 'avec lecteur Blu-ray']::text[], array['Ne s''allume plus', 'Port HDMI', 'Surchauffe', 'Lecteur Blu-ray']::text[], true
  from public.brands b where b.slug = 'playstation'
on conflict (slug) do nothing;
insert into public.console_models (brand_id, name, slug, short_name, release_year, display_order, family, is_retro, is_handheld, variants, common_issues, is_active)
select b.id, 'PlayStation 5 Digital Edition', 'ps5-digital', 'PS5 Digital', 2020, 8, 'ps5', false, false,
       array['Digital (CFI-1000B à 1200B)', 'sans lecteur']::text[], array['Ne s''allume plus', 'Port HDMI', 'Surchauffe', 'SSD non reconnu']::text[], true
  from public.brands b where b.slug = 'playstation'
on conflict (slug) do nothing;
insert into public.console_models (brand_id, name, slug, short_name, release_year, display_order, family, is_retro, is_handheld, variants, common_issues, is_active)
select b.id, 'PlayStation 5 Slim', 'ps5-slim', 'PS5 Slim', 2023, 9, 'ps5', false, false,
       array['Slim (CFI-2000)', 'lecteur Blu-ray amovible']::text[], array['Ne s''allume plus', 'Port HDMI', 'Lecteur amovible non reconnu']::text[], true
  from public.brands b where b.slug = 'playstation'
on conflict (slug) do nothing;
insert into public.console_models (brand_id, name, slug, short_name, release_year, display_order, family, is_retro, is_handheld, variants, common_issues, is_active)
select b.id, 'PlayStation 5 Slim Digital Edition', 'ps5-slim-digital', 'PS5 Slim Digital', 2023, 10, 'ps5', false, false,
       array['Slim Digital (CFI-2000B)', 'lecteur en option']::text[], array['Ne s''allume plus', 'Port HDMI', 'Surchauffe']::text[], true
  from public.brands b where b.slug = 'playstation'
on conflict (slug) do nothing;
insert into public.console_models (brand_id, name, slug, short_name, release_year, display_order, family, is_retro, is_handheld, variants, common_issues, is_active)
select b.id, 'PlayStation 5 Pro', 'ps5-pro', 'PS5 Pro', 2024, 11, 'ps5', false, false,
       array['Pro (CFI-7000)', 'lecteur en option']::text[], array['Surchauffe', 'Port HDMI', 'Ventilateur bruyant']::text[], true
  from public.brands b where b.slug = 'playstation'
on conflict (slug) do nothing;

